/* Intermediate11 — data protection, protection metadata and honest detection boundaries. */
(function () {
  const N=AG.aws.n, clone=x=>JSON.parse(JSON.stringify(x));
  const canonical=(x,key='')=>{if(['Action','Resource','AWS'].includes(key)&&(typeof x==='string'||Array.isArray(x)&&x.every(v=>typeof v==='string')))return (Array.isArray(x)?x:[x]).slice().sort();if(Array.isArray(x)){const rows=x.map(v=>canonical(v));if(rows.every(v=>v&&typeof v==='object'&&typeof v.Sid==='string'))rows.sort((a,b)=>a.Sid.localeCompare(b.Sid));else if(rows.every(v=>v&&typeof v==='object'&&Number.isInteger(v.Priority)))rows.sort((a,b)=>a.Priority-b.Priority);return rows;}if(x&&typeof x==='object')return Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k],k)]));return x;};
  const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
  const R='us-east-1', A='123456789012', ROOT=`arn:aws:iam::${A}:root`, REVIEW=`arn:aws:iam::${A}:role/security-reviewer`;
  const ID='00000000-0000-4000-8000-000000000001', KEY=`arn:aws:kms:${R}:${A}:key/${ID}`, OLD='invoice-archive-key', OLDARN=`arn:aws:kms:${R}:${A}:key/${OLD}`;
  const ALB=`arn:aws:elasticloadbalancing:${R}:${A}:loadbalancer/app/shop-alb/000001`, ACLID='00000000-0000-4000-9000-000000000001', ACL=`arn:aws:wafv2:${R}:${A}:regional/webacl/shop-login/${ACLID}`;
  const ROTATOR=`arn:aws:lambda:${R}:${A}:function:db-secret-rotator`, SECRET='shop/db', PARAM='/shop/payment-token';
  const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
  const admin={Sid:'PreserveAdministration',Effect:'Allow',Principal:{AWS:ROOT},Action:'kms:*',Resource:'*'};
  const keyPolicy={Version:'2012-10-17',Statement:[admin,{Sid:'InvoiceReader',Effect:'Allow',Principal:{AWS:REVIEW},Action:'kms:Decrypt',Resource:'*',Condition:{StringEquals:{'kms:EncryptionContext:tenant':'shopkaro'}}}]};
  const vis={SampledRequestsEnabled:true,CloudWatchMetricsEnabled:true,MetricName:'shop-login'};
  const rules=[{Name:'Common',Priority:0,Statement:{ManagedRuleGroupStatement:{VendorName:'AWS',Name:'AWSManagedRulesCommonRuleSet'}},OverrideAction:{None:{}},VisibilityConfig:vis},{Name:'LoginRate',Priority:1,Statement:{RateBasedStatement:{Limit:100,EvaluationWindowSec:60,AggregateKeyType:'IP',ScopeDownStatement:{ByteMatchStatement:{SearchString:'/login',FieldToMatch:{UriPath:{}},TextTransformations:[{Priority:0,Type:'NONE'}],PositionalConstraint:'EXACTLY'}}}},Action:{Block:{}},VisibilityConfig:vis}];
  const enc={Rules:[{ApplyServerSideEncryptionByDefault:{SSEAlgorithm:'aws:kms',KMSMasterKeyID:KEY},BucketKeyEnabled:true}]};
  const value='{"username":"test_app","password":"TEST_ONLY_lab_password"}';
  const files={};
  for(const [name,content,desc] of [['key-policy.json',keyPolicy,'Reviewed admin plus context-scoped reviewer decrypt'],['encryption.json',enc,'Default SSE-KMS for future writes; existing objects retain original encryption'],['waf-rules.json',rules,'Reviewed CommonRuleSet and exact /login IP rate rule'],['visibility.json',vis,'Metrics and sampled requests enabled'],['rotation.json',{AutomaticallyAfterDays:30},'Rotation schedule configuration only; function runtime unverified']])files[name]={desc,content:JSON.stringify(content,null,2)};
  files['secret.json']={desc:'Dummy training secret only; never paste a real credential',content:value};
  files['invoice-cipher.bin']={desc:'Opaque local TEST ciphertext handle, not real KMS wire bytes',content:'LOCAL-ARCHIVE-INVOICE'};
  function seed(interview=false){return {region:R,securityScope:true,callerIdentity:{Account:A,Arn:interview?REVIEW:ROOT,UserId:'TRAINING'},kmsKeys:[{id:OLD,arn:OLDARN,fixtureId:'original-archive-key',state:interview?'Disabled':'Enabled',revision:1,policy:{Version:'2012-10-17',Statement:[{...admin,Action:['kms:DescribeKey','kms:PutKeyPolicy','kms:EnableKey']}]}}],kmsAliases:[],kmsCiphertexts:[{token:'LOCAL-ARCHIVE-INVOICE',keyId:OLD,context:{tenant:'shopkaro',purpose:'invoice'},plaintext:'TEST invoice101 INR2500'}],buckets:[{name:'shop-invoices',bucketId:'original-invoices',region:R,encryption:true,public:false,objects:[{key:'existing.txt',body:'TEST old invoice',size:16,serverSideEncryption:'AES256',etag:'"original"'}]}],secrets:[],parameters:[],webAcls:[],elbs:[{id:ALB,arn:ALB,name:'shop-alb',fixtureId:'original-alb',type:'application',scheme:'internet-facing',state:'active'}],lambdas:[{name:'db-secret-rotator',fixtureId:'reviewed-rotation-function',runtime:'python3.12',handler:'app.handler',state:'Active',memory:512,timeout:30}],detectors:[{id:'detector-shop',enabled:true,findings:[{Id:'training-exfiltration',Type:'UnauthorizedAccess:IAMUser/InstanceCredentialExfiltration.OutsideAWS',Severity:8,Title:'TRAINING: instance credentials used outside AWS',Description:'Seeded lesson fixture; not a live detected event'}]}]};}
  const mainSolution=[
    'aws kms create-key --description shop-invoices --policy file://key-policy.json',
    `aws kms create-alias --alias-name alias/shop-invoices --target-key-id ${ID}`,
    `aws kms enable-key-rotation --key-id ${ID} --rotation-period-in-days 180`,
    'aws s3api put-bucket-encryption --bucket shop-invoices --server-side-encryption-configuration file://encryption.json',
    `aws secretsmanager create-secret --name ${SECRET} --kms-key-id ${KEY} --secret-string file://secret.json`,
    `aws secretsmanager rotate-secret --secret-id ${SECRET} --rotation-lambda-arn ${ROTATOR} --rotation-rules file://rotation.json --no-rotate-immediately`,
    `aws secretsmanager get-secret-value --secret-id ${SECRET}`,
    `aws ssm put-parameter --name ${PARAM} --type SecureString --key-id ${KEY} --value TEST_ONLY_api_token`,
    `aws ssm get-parameter --name ${PARAM} --with-decryption`,
    'aws wafv2 create-web-acl --name shop-login --scope REGIONAL --cli-binary-format raw-in-base64-out --default-action \'{"Allow":{}}\' --rules file://waf-rules.json --visibility-config file://visibility.json',
    `aws wafv2 associate-web-acl --web-acl-arn ${ACL} --resource-arn ${ALB}`,
    `aws wafv2 get-web-acl-for-resource --resource-arn ${ALB}`
  ];
  const original=s=>{const a=s.account,k=a.kmsKeys.find(k=>k.id===OLD),b=a.buckets.find(b=>b.name==='shop-invoices'),lb=a.elbs.find(l=>l.id===ALB);return !!k&&k.fixtureId==='original-archive-key'&&k.state==='Enabled'&&!!b&&b.bucketId==='original-invoices'&&!b.public&&b.objects.length===1&&b.objects[0].body==='TEST old invoice'&&b.objects[0].serverSideEncryption==='AES256'&&lb?.fixtureId==='original-alb'&&a.lambdas.some(f=>f.fixtureId==='reviewed-rotation-function'&&f.name==='db-secret-rotator');};
  const tasks=[
    {text:'Original invoices, archive key, ALB and reviewed rotation function preserved',check:original},
    {text:'Enabled customer key with reviewed policy, alias and 180-day rotation',check:s=>{const k=s.account.kmsKeys.find(k=>k.id===ID);return !!k&&k.state==='Enabled'&&same(k.policy,keyPolicy)&&k.rotation?.period===180&&s.account.kmsKeys.length===2&&s.account.kmsAliases.some(a=>a.name==='alias/shop-invoices'&&a.keyId===ID);}},
    {text:'Future-write bucket default uses new key/Bucket Key; old object remains unchanged',check:s=>{const b=s.account.buckets.find(b=>b.name==='shop-invoices');return b?.encryption==='kms'&&b.kmsKey===KEY&&b.bucketKey===true;}},
    {text:'Current TEST secret retrievable, with 30-day rotation CONFIG only; runtime unverified',check:s=>{const v=s.account.secrets.find(v=>v.name===SECRET&&!v.deleted),k=s.account.kmsKeys.find(k=>k.id===ID);return !!v&&!!k&&k.state==='Enabled'&&v.keyId===KEY&&v.rotation?.lambdaArn===ROTATOR&&v.rotation.rules.AutomaticallyAfterDays===30&&v.rotation.runtime==='UNVERIFIED'&&v.versions.some(x=>x.value===value&&x.stages.includes('AWSCURRENT')&&(s.account.securityReads||[]).some(r=>r.kind==='secretValue'&&r.arn===v.arn&&r.versionId===x.id&&r.revision===v.revision&&r.value===value));}},
    {text:'Separate SecureString TEST token uses new key; decrypted current version read',check:s=>{const p=s.account.parameters.find(p=>p.name===PARAM);return p?.type==='SecureString'&&p.keyId===KEY&&p.value==='TEST_ONLY_api_token'&&(s.account.securityReads||[]).some(r=>r.kind==='parameter'&&r.name===PARAM&&r.version===p.version&&r.value===p.value);}},
    {text:'Reviewed enforcing WAF metadata associated with original ALB, then current association read',check:s=>{const a=s.account.webAcls.find(a=>a.arn===ACL);return !!a&&a.scope==='REGIONAL'&&same(a.defaultAction,{Allow:{}})&&same(a.rules,rules)&&same(a.visibility,vis)&&s.account.elbs.find(l=>l.id===ALB)?.webAclArn===ACL&&(s.account.securityReads||[]).some(r=>r.kind==='wafAssociation'&&r.resource===ALB&&r.aclId===a.id&&r.revision===a.revision);}}
  ];
  const interviewSolution=[`aws kms enable-key --key-id ${OLD}`,`aws kms put-key-policy --key-id ${OLD} --policy-name default --policy file://key-policy.json`,'aws kms decrypt --key-id '+OLD+' --ciphertext-blob fileb://invoice-cipher.bin --encryption-context \'{"tenant":"shopkaro","purpose":"invoice"}\''];
  const itasks=[{text:'Original archive key enabled; original opaque invoice retained',check:s=>s.account.kmsKeys.length===1&&s.account.kmsKeys[0].fixtureId==='original-archive-key'&&s.account.kmsKeys[0].state==='Enabled'&&s.account.kmsCiphertexts.length===1&&s.account.kmsCiphertexts[0].plaintext==='TEST invoice101 INR2500'},{text:'Reviewed key policy restored with exact tenant-scoped reviewer decrypt',check:s=>same(s.account.kmsKeys[0]?.policy,keyPolicy)},{text:'Actual matching original TEST ciphertext decrypted at current key revision',check:s=>{const k=s.account.kmsKeys[0];return !!k&&k.state==='Enabled'&&AG.securityKeyAllowed(s.account,k,'kms:Decrypt',{tenant:'shopkaro',purpose:'invoice'})&&(s.account.securityReads||[]).some(r=>r.kind==='decrypt'&&r.token==='LOCAL-ARCHIVE-INVOICE'&&r.keyId===OLD&&r.revision===k.revision&&r.plaintext==='TEST invoice101 INR2500');}}];
  const cost=k=>{const baseline=k.objects*1000000*(1+k.reads),fraction=[0,.5,.9,.99][k.reuse],calls=k.bucket?Math.ceil(baseline*(1-fraction)):baseline,key=1+Math.min(k.rotations,2);return {baseline,calls,before:key+baseline*.03/10000,after:key+calls*.03/10000,key};};
  AG.registerLevels('intermediate',[{
    id:'security',icon:'🛡️',title:'Security — data, edge aur evidence',badge:'Security Senapati',
    objectives:['KMS policy/context/rotation aur envelope encryption debug karna','Secret value, backend credential aur rotation configuration alag verify karna','WAF protection metadata aur real traffic evidence distinguish karna','Detection services choose karke monitored response plan banana'],
    hook:{when:'ShopKaro course story — fictional',title:'Mahasale se pehle chaar security tickets',text:'ShopKaro login par 50,000 requests/min aa rahe hain. Ravi ka DB password chat mein mil gaya. Ek EC2 mining-pool domain contact kar raha hai. Auditor poochta hai: invoices kaun decrypt kar sakta hai? Neha ko service list nahi, har risk ka owner aur proof chahiye.',mission:'Abhi defense map dekho. Phir key/secret/WAF configuration repair karo aur actual state read karo. Course fixtures fictional hain; Capital One ka sourced case alag labelled hai.'},
    steps:[
      {q:'Firewall, encryption aur detection ek problem kyun solve nahi karte?',analogy:'Shop ka guard crowd control karta hai, locker cash protect karta hai, CCTV evidence deta hai. CCTV recording locker ki missing key fix nahi karti.',body:'<p>Threat ko actor/action/resource mein likho. Edge WAF inspects supported HTTP entry points; SG/NACL network paths control karte hain; IAM permissions decide karta hai; KMS key use authorize karta hai. Detection ko owner, alert route aur response runbook chahiye.</p>',points:['Galti jo sab karte hain: GuardDuty finding ko blocked attack samajhna. Detection ke baad containment, evidence preservation, credential revocation and verification assign karo.','Production me kya hota hai: direct origin path CDN protection bypass kar sakta hai; broad IAM role encrypted data read kar sakta hai. Har layer ka coverage aur bypass path review karo.','Hands-on: next dry run mein IP traffic aur key authorization ko separate panels mein follow karo. Expected: WAF action changes HTTP handling, not kms:Decrypt permission.'],asli:'Choose the control that addresses the observed risk; review residual risk and measurable evidence.'},
      {q:'KMS se 7,000-byte invoice directly encrypt karenge?',analogy:'Bada parcel locker mein rakho. Parcel key chhoti hai; master locker sirf parcel key protect karta hai.',body:'<p>Symmetric KMS Encrypt handles up to 4,096 bytes. GenerateDataKey returns plaintext data key plus wrapped ciphertext key. Application encrypts payload locally, stores ciphertext, nonce, wrapped key and context, then removes plaintext key material from normal use. Decrypt first unwraps the key, then authenticates/decrypts the payload.</p>',points:['EncryptionContext is non-secret case-sensitive authenticated metadata. Encrypt/Decrypt need exactly matching context; context may appear in logs, so password/PII mat daalo.','AWS owned keys are service-controlled; AWS managed keys offer an account-visible service key with uneditable policy; customer managed keys provide policy/grants/lifecycle control and cost. Dedicated HSM/PKCS#11 requirements can justify CloudHSM. Client-side encryption changes where plaintext is exposed.','Action: lab19 ex1 runs actual AES-GCM host roundtrip and tamper failure. The in-app opaque handles only model key/context/access state; handles are not encryption.'],code:'aws kms generate-data-key --key-id alias/shop-invoices --key-spec AES_256 --encryption-context \'{"tenant":"shopkaro"}\'',asli:'Use a reviewed encryption SDK/format in production; a toy envelope omits secure memory handling and operational key recovery.'},
      {q:'S3 read allowed hai; KMS AccessDenied kyun?',analogy:'Invoice room ka gate pass aur locker access dono alag approvals hain. Gate pass locker authority create nahi karta.',body:'<p>SSE-KMS reads need S3 authorization and a usable KMS key with an applicable key-policy/IAM/grant path. Explicit Deny can override an Allow. A root-account key-policy delegation enables IAM permissions; a direct principal Allow is another path. Cross-account use needs the relevant permissions on both sides.</p>',points:['Customer managed symmetric AWS_KMS automatic rotation is opt-in, configurable 90–2,560 days, default 365 days. AWS managed keys rotate annually. Imported symmetric material supports eligible on-demand rotation; asymmetric/HMAC/custom-store cases have different rules. Rotation preserves key ID and old decrypt material; existing data is not rewritten.','New default SSE-KMS/BucketKeyEnabled affects future writes. Existing objects need a deliberate migration. Bucket Keys can reduce calls up to 99%, depending on requesters/workload; cached use does not produce one KMS audit event per object read or an immediate per-request key-policy recheck.','Action: compare GetBucketEncryption with old HeadObject. Interview separately restores an existing disabled key, narrow policy and exact context; creating a new key cannot decrypt old ciphertext.'],code:'aws kms enable-key-rotation --key-id '+ID+' --rotation-period-in-days 180',asli:'Deletion is different from rotation. ScheduleKeyDeletion waits7–30days; cancellation leaves the key Disabled. Review dependencies and recovery before enabling/deleting.'},
      {q:'Secret store karna aur credential rotate karna alag kyun?',analogy:'New office lock ki key register mein likhna enough nahi. Lock change, new key test aur staff key refresh coordinate karo.',body:'<p>Secrets Manager purpose-built secret versions/rotation/replication deta hai. Parameter Store config ke liye useful hai: SecureString encrypts with KMS, but has no built-in credential rotation. Standard parameter size 4 KiB, Advanced 8 KiB; storage/throughput/KMS charges depend on selected features.</p>',points:['Lambda rotation pattern: createSecret→setSecret in actual backend→testSecret→finishSecret stage promotion. AWSPENDING is not working AWSCURRENT. App caches need bounded refresh and recovery after rotation; never log real secret values.','RotationEnabled describes configuration, not successful password change. --no-rotate-immediately still invokes testSecret on AWS. Native managed service/external-secret integrations have their own supported setup; no blanket “every password automatically30days” rule.','Action: inspect secret.json (TEST_ONLY), store/retrieve current value, then lab19 ex3 compares pending/current labels with a TEST backend dict. Docker/real DB/Lambda rotation remains unverified.'],code:'aws secretsmanager get-secret-value --secret-id shop/db\naws ssm get-parameter --name /shop/payment-token --with-decryption',asli:'Approx US East Secrets Manager $0.40/secret/month +$0.05/10000API calls; rotation Lambda/KMS/replicas can add cost. A Parameter Store notification policy does not rotate a backend credential.'},
      {q:'TLS certificate ka Region aur renewal owner kaun?',analogy:'Shop license approved hona aur har branch par updated copy lagna alag kaam hain.',body:'<p>ACM non-exportable public certificates have no certificate charge with integrated AWS services; supported exportable public/ACME and Private CA options are billed separately. ACM manages eligible renewal, but DNS/email validation and deployment conditions matter.</p>',points:['ALB uses a certificate in the ALB Region. CloudFront viewer certificate comes from ACM us-east-1. API Gateway certificate Region depends on endpoint type; inspect the exact integration.','Exportable certificates can be used outside integrated services, but the operator must deploy renewed certificate/key material. Do not teach “ACM public certificates can never be exported”.','Action: name the TLS termination point before choosing certificate Region. Production check: hostname/SAN, chain, expiry, renewal eligibility and deployed serial.'],asli:'A successful certificate request is configuration evidence; validate the served TLS endpoint and renewal/deployment monitoring.'},
      {q:'100requests/60s WAF rule stops every login bot?',analogy:'Guard ek line ka crowd count karta hai.10000alag lines mein thoda-thoda crowd single-line threshold ke neeche reh sakta hai.',body:'<p>WAF web ACLs attach to supported HTTP resources. Managed rule groups help inspect known patterns; rate rules aggregate matching traffic over 60/120/300/600 s windows (default300). Minimum configured limit 10. Rate estimation/propagation means the threshold is not an exact API quota.</p>',points:['Rule priority and terminating actions matter. Deploy Count for observation, inspect legitimate traffic/false positives, then reviewed Block/Challenge/CAPTCHA as appropriate. In this mission CommonRuleSet OverrideAction None and /login rate Action Block are the intended enforcing metadata.','Distributed bots, shared NAT users, trusted proxy IP headers, credential-stuffing accounts and origin bypass need separate analysis. Bot Control/ATP, account controls/MFA and app query/input fixes complement WAF; SQLi protection also needs parameterized queries.','Shield Standard supplies baseline DDoS protection; Advanced adds paid features and eligible protections/response under conditions. Approx subscription $3,000/month with a one-year minimum commitment; protected-resource data transfer and premium features can add cost. Advanced is not an automatic refund or account-wide protection without resource/config review. Firewall Manager centralizes supported policies across accounts.','Action: lab19 creates a Regional ACL/ALB association and rejects stale LockToken. No HTTP filtering or bot suppression is measured by Moto or the in-app configuration model.'],asli:'Protect the actual entry path. CloudFront uses CLOUDFRONT scope in us-east-1; ALB uses same-Region REGIONAL scope. Review current pricing/commitments before buying Advanced.'},
      {q:'Finding, vulnerability, PII aur compliance evidence kis service se?',analogy:'CCTV suspicious behavior dikhata hai, building inspection weak locks dikhati hai, records audit sensitive files identify karta hai.',body:'<div class="tbl-wrap"><table class="security-table"><tr><th>Need</th><th>Candidate / limit</th></tr><tr><td>Threat signals</td><td>GuardDuty; review plan/Region/resource coverage</td></tr><tr><td>Software vulnerability</td><td>Inspector; supported EC2/ECR/Lambda coverage</td></tr><tr><td>S3 sensitive data</td><td>Macie; discovery scope, not data masking</td></tr><tr><td>Resource compliance</td><td>Config rules; remediation is separate</td></tr><tr><td>Security posture/findings</td><td>Security Hub; enabled integrations and controls</td></tr><tr><td>Investigation relationships</td><td>Detective; supported data/coverage</td></tr><tr><td>API evidence</td><td>CloudTrail; management/data-event scope matters</td></tr></table></div>',points:['GuardDuty foundational analysis uses independent supported CloudTrail management/flow/DNS data streams. Optional plans include S3, EKS/RDS, Lambda, malware, runtime and AI-related coverage; features/billing/availability differ. Runtime Monitoring uses a security agent, so “GuardDuty never uses an agent” is wrong.','Action: list-detectors→get-findings for detector-shop/training-exfiltration. Expected: seeded TRAINING finding, not a live event. Assign incident owner; contain affected workload/credentials, preserve evidence, investigate scope and verify recovery.','Production me kya hota hai: alert fatigue, unsupported/uncovered workloads and missing response ownership leave findings unresolved. Encrypting with KMS does not stop an authorized stolen role from reading data.'],asli:'Detection confidence/coverage and response time must be measured. Enabling a detector does not prove a breach would have been prevented.'},
      {q:'Customer login aur workforce AWS access kaise separate karein?',analogy:'Customers ka shopping account aur employees ka warehouse master access alag identity systems hain.',body:'<p>Cognito user pools handle app sign-up/sign-in/JWTs; identity pools exchange supported identities for scoped temporary AWS credentials. IAM Identity Center serves workforce access; workload IAM roles serve EC2/Lambda/ECS. Tokens still need issuer/audience/expiry validation and appropriate API authorization.</p><p><b>Sourced incident: Capital One 2019.</b> <a href="https://www.justice.gov/usao-wdwa/united-states-v-paige-thompson" target="_blank" rel="noopener noreferrer">DOJ describes intrusion</a> through a misconfigured web application firewall. <a href="https://www.capitalone.com/digital/facts2019/" target="_blank" rel="noopener noreferrer">Capital One reports</a> approx 100 million US and 6 million Canadian individuals affected. The case motivates SSRF/metadata defenses and least-privilege review; the lesson does not claim a particular missing service would certainly have prevented the incident.</p>',points:['IMDSv2 token-based metadata access reduces relevant SSRF exposure; require supported instance settings and review role reach. Application SSRF controls, least privilege and monitoring remain separate.','GuardDuty documents InstanceCredentialExfiltration.OutsideAWS for relevant patterns. Detection capability is not proof of what would have happened in the 2019 incident.','Action: Decision Dojo identity tree mein customer login versus workforce/code branches compare karo. Advanced appai provides the full Cognito lab.'],asli:'Choose identity by actor and trust boundary, then test authorization. A signed user token alone does not authorize every object/action.'}
    ],
    myth:[{myth:'Rotation rewrites old objects and fixes leaked passwords.',sach:'KMS material rotation preserves old decryptability. Object migration and backend credential rotation are separate operations.'},{myth:'Bucket Keys give exactly99% saving and per-object KMS audit.',sach:'Savings depend on requester/workload/cache; cached use reduces KMS calls and related audit events.'},{myth:'WAF Count and GuardDuty finding mean the attack was blocked.',sach:'Count observes; GuardDuty detects supported signals. Enforcing actions and monitored response need separate proof.'},{myth:'Every public ACM cert is free/non-exportable; every GuardDuty plan is agentless.',sach:'ACM certificate modes differ; optional GuardDuty Runtime Monitoring uses an agent. Check the exact integration/plan.'}],
    playbook:{title:'Risk se control choose karo',use:['Key policy/audit/lifecycle requirement→customer managed KMS; simple S3 at-rest need→SSE-S3 can fit','Backend credential lifecycle→Secrets Manager; config without rotation→Parameter Store','HTTP pattern/rate signals→WAF; threat evidence→GuardDuty plus incident owner'],avoid:['Encryption ko authorization/backup replacement samajhna','RotationEnabled, detector ENABLED ya ACL association ko runtime protection proof samajhna'],how:['Identify actor/action/resource and required evidence','Choose prevention/detection/response owners; test narrow access and negative paths','Validate actual bytes/backend credential/traffic outcome in the appropriate runtime'],redflags:['Wildcard key decrypt, old key deleted, no recovery inventory','Secret label promoted before backend test, logs containing credentials','WAF origin bypass, Count-only rollout forgotten, findings without response'],rule:'Configuration → access → actual outcome: har boundary ka alag proof.',compare:{heads:['Need','Choose','Trade-off'],rows:[['Simple S3 encryption','SSE-S3','No customer key policy/lifecycle control'],['Fine key governance','Customer managed KMS','Cost, quotas and key dependency'],['Credential rotation','Secrets Manager','Backend/consumer recovery still required'],['Config values','Parameter Store','No built-in credential rotation'],['HTTP attack patterns','WAF','False positives, coverage and bypass review'],['Threat signals','GuardDuty','Coverage and response ownership']]},trees:['encryption','secrets','firewall','identity']},
    exam:[{cue:'Envelope encryption',pick:'local data encryption plus KMS-wrapped data key'},{cue:'SSE-KMS read',pick:'S3 permission plus usable authorized key'},{cue:'Customer rotation period',pick:'eligible90–2560days, not fixed yearly'},{cue:'Bucket default',pick:'future objects; Bucket Key savings up to 99%, workload dependent'},{cue:'Secrets rotation',pick:'backend set/test and version promotion, not only stored config'},{cue:'CloudFront viewer certificate',pick:'ACM us-east-1'},{cue:'SQLi/rate signals',pick:'WAF; DDoS features→Shield; centralized policies→Firewall Manager'},{cue:'Threat / vulnerability / PII / compliance',pick:'GuardDuty / Inspector / Macie / Config'},{cue:'Customer login',pick:'Cognito; workforce→Identity Center; code→IAM role'}],
    lesson:['<h3>Kab kya — decision map</h3><div class="tbl-wrap"><table class="security-table"><tr><th>Observed need</th><th>Candidate</th><th>Boundary</th></tr><tr><td>S3 at-rest baseline</td><td>SSE-S3</td><td>Customer key lifecycle unavailable</td></tr><tr><td>Key policy/audit control</td><td>Customer managed KMS</td><td>Cost, quotas and dependency recovery</td></tr><tr><td>Backend credential rotation</td><td>Secrets Manager</td><td>Backend test and app refresh required</td></tr><tr><td>Config without rotation</td><td>Parameter Store</td><td>Tier/throughput/KMS reviewed</td></tr><tr><td>HTTP attack signals</td><td>WAF</td><td>False positives and bypass paths</td></tr><tr><td>Suspicious activity</td><td>GuardDuty</td><td>Coverage plus response owner</td></tr></table></div><p><b>Decision tree:</b> Data unreadable? Check object key→key state→policy/context. Credential lifecycle? Need backend rotation→Secrets Manager; config only→Parameter Store. HTTP abuse? WAF plus app controls; suspicious AWS activity→GuardDuty plus incident response. Customer login→Cognito; employee AWS access→Identity Center.</p>'],
    stages:[
      {type:'dryrun',lesson:'HTTP enforcement, key authorization and credential backend outcomes need separate evidence. Configuration readback is one boundary, not a completed protection test.',title:'🧪 Login attack aur invoice read alag boundaries',intro:'Course fixture: one noisy IP, then distributed bots; a separate invoice read fails KMS access. Click each step; panel text explains the proof.',nodes:[N('app',150,150,{label:'Client'}),N('waf',460,150,{label:'WAF'}),N('ec2',770,150,{label:'App role'}),N('kms',770,420,{label:'KMS'}),N('s3',460,420,{label:'Invoice'})],edges:[{from:'app',to:'waf'},{from:'waf',to:'ec2'},{from:'ec2',to:'kms'},{from:'kms',to:'s3'}],panels:[{id:'edge',title:'HTTP / protection'},{id:'data',title:'Key / data evidence'}],steps:[
        {say:'One source exceeds the configured /login IP rate signal. Reviewed Block action can mitigate matching traffic after WAF estimation/propagation.',flows:[{from:'app',to:'waf',label:'login'}],panels:{edge:['IP 100 requests/60 s threshold is approximate','Count observes; Block enforces'],data:['No change to kms:Decrypt authorization']}},
        {say:'The botnet spreads attempts across10,000 IPs, each below the configured per-IP limit.',ask:Q('What follows from the distributed low-rate bot traffic?', 'Per-IP rate control may miss the pattern; add account/bot signals and review legitimate users',['Every request is blocked because one IP rate threshold applies to all AWS accounts combined','Raising KMS rotation frequency stops the bots because encryption controls login request counts','Disabling WAF metrics prevents credential stuffing because attackers can no longer see graphs'],0,'Aggregation is per configured key, so distributed bots can evade a per-IP rule. Account/MFA/bot controls complement WAF; KMS rotation and metrics visibility do not authenticate login attempts.'),panels:{edge:['Review account signals, bot controls and shared-NAT false positives'],data:['Detection and response ownership remain separate']}},
        {say:'The app reads an SSE-KMS invoice. S3 permission is allowed, but the selected KMS key is disabled. No plaintext read is proven.',flows:[{from:'ec2',to:'kms',label:'decrypt',tone:'bad'}],panels:{edge:['WAF configuration did not grant key use'],data:['DisabledException','Inspect key state before permissions/context']},ask:Q('Which repair preserves the original encrypted invoice?', 'Review/re-enable the original key, then verify the authorized principal and exact encryption context',['Create another key with the same description because equal names reproduce the old key material','Replace the invoice with an empty object because zero bytes prove that encryption is working','Make the bucket public because public S3 policy automatically overrides every KMS key state'],1,'Original ciphertext depends on original key material. A new key cannot decrypt the old blob; replacement loses data; bucket public access does not override KMS. Actual access/context still need verification after enable.' )},
        {say:'Envelope encryption unwraps a small data key using non-secret tenant context. Actual payload authentication/decryption happens locally.',flows:[{from:'kms',to:'s3',label:'unwrap',tone:'ok'}],panels:{data:['Exact context and usable authorized key','Host AES-GCM tamper check is in lab19']}},
        {say:'A new secret version is AWSPENDING while the backend still accepts the old password. A label alone does not change the backend.',panels:{edge:['App uses current credential until reviewed rotation completes'],data:['Set backend→test pending credential→promote current']},ask:Q('When is promoting a pending credential justified?', 'After the intended backend accepts the new credential and recovery/client refresh have been reviewed',['As soon as PutSecretValue returns a VersionId because backend passwords update implicitly','After enabling a GuardDuty detector because detector status validates database authentication','Before testing the backend because a current label forces the database to accept the password'],2,'The rotation workflow coordinates backend and secret, then validates before promotion. PutSecretValue only stores data; GuardDuty does not authenticate a DB; labels cannot force backend password changes.')},
        {say:'Read current association/key/secret state. Configuration is ready for runtime validation; no bot block, Lambda rotation or live threat finding is claimed locally.',panels:{edge:['WAF association/config metadata verified','Runtime traffic test remains separate'],data:['Actual host crypto + staged TEST credential reference','Moto gaps documented; cleanup verified']}}
      ]},
      {type:'flowlab',title:'🎛️ KMS request cost — declared reuse scenario',goal:'Preserve at least 3 million objects/month and 2 reads/object. Enable Bucket Keys for a declared reuse scenario that reduces modeled KMS request count ≥80% and total KMS cost ≤$20/month. Start: choose 90% reuse and enable Bucket Keys.',scenario:'Approx US East gross model: one KMS call per declared write/read without reuse, $0.03/10,000 eligible symmetric calls. A customer key costs $1/month plus first two retained material rotations at $1 each. Reuse percentage is an assumed measured input, not an AWS prediction or guaranteed 99%. Actual requester/cache/operations determine savings. S3, logging, transfer, tax, allowances and other crypto APIs excluded.',knobs:[{id:'objects',label:'Objects written / month',min:1,max:5,step:1,value:5,fmt:v=>v+' million'},{id:'reads',label:'Reads per object',min:1,max:5,step:1,value:3,fmt:v=>v+' reads/object'},{id:'reuse',label:'Declared request reduction with Bucket Key',min:0,max:3,step:1,value:0,labels:{0:'0%',1:'50%',2:'90%',3:'99%'}},{id:'bucket',label:'Bucket Key enabled',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On'}},{id:'rotations',label:'Billable retained rotations',min:0,max:2,step:1,value:0,fmt:v=>v+' rotations'}],model:k=>{const c=cost(k),ok=k.objects>=3&&k.reads>=2&&k.bucket===1&&c.calls<=.2*c.baseline&&c.after<=20;return {readouts:[{label:'Baseline declared KMS calls',value:c.baseline.toLocaleString('en-US')+' calls/month'},{label:'Selected modeled KMS calls',value:c.calls.toLocaleString('en-US')+' calls/month'},{label:'Key/material gross cost',value:'$'+c.key.toFixed(2)+'/month'},{label:'Baseline KMS gross',value:'$'+c.before.toFixed(2)+'/month'},{label:'Selected KMS gross',value:'$'+c.after.toFixed(2)+'/month'}],verdict:{ok,text:ok?'Declared workload and budget fit this assumed request-reuse scenario. Measure real savings and audit coverage.':'Retain required workload, then choose enabled Bucket Key and sufficient declared reuse; compare budget.'}};},check:k=>{const c=cost(k);return k.objects>=3&&k.reads>=2&&k.bucket===1&&c.calls<=.2*c.baseline&&c.after<=20;},lesson:'Default workload 20 million calls/month costs approx $61 KMS gross; assumed 90% reduction gives 2 million calls and approx $7. Cached Bucket Key requests need not call KMS, so object-level audit may need S3 data events. This model does not measure caching or instant key revocation.'},
      {type:'bins',title:'Prevention, detection ya coordinated recovery?',instructions:'Service ka primary role choose karo. Combined systems mein roles overlap ho sakte hain; labels describe the stated action.',bins:[{id:'prevent',label:'Prevent / restrict'},{id:'detect',label:'Detect / evidence'},{id:'recover',label:'Coordinate recovery'}],items:[{text:'WAF reviewed Block rule on the actual HTTP entry point',bin:'prevent',explain:'Matching request handling can be restricted; Count would only observe.'},{text:'KMS narrow decrypt policy for a tenant context',bin:'prevent',explain:'Key authorization limits plaintext access; context is non-secret authenticated metadata.'},{text:'GuardDuty finding with an assigned incident owner',bin:'detect',explain:'Finding is a threat signal; containment/verification are separate work.'},{text:'Macie discovers sensitive values in selected S3 objects',bin:'detect',explain:'Discovery/classification does not mask or delete those values.'},{text:'Secret rotation sets/tests backend then promotes current',bin:'recover',explain:'Credential lifecycle coordinates backend, versions and client refresh.'},{text:'CloudTrail selected management/data events reviewed',bin:'detect',explain:'Audit scope must include the relevant actions; no automatic prevention.'}]},
      {type:'triage',title:'🩺 GetObject allowed, KMS access denied',symptom:'TRAINING app role has s3:GetObject and IAM kms:Decrypt. Original invoice key is Enabled; its key policy has no direct app Allow or account delegation for decrypt.',goal:'Identify the actual authorization boundary before widening access.',commands:[{cmd:'aws s3api head-object --bucket shop-invoices --key invoice101',out:'ServerSideEncryption: aws:kms\nSSEKMSKeyId: invoice-archive-key',clue:false,note:'Existing object key matters; changing bucket default cannot rewrite the object.'},{cmd:'aws kms describe-key --key-id invoice-archive-key',out:'KeyState: Enabled',clue:false,note:'Key state is usable; inspect authorization next.'},{cmd:'aws kms get-key-policy --key-id invoice-archive-key --policy-name default',out:'TRAINING policy permits management only; no kms:Decrypt app Allow or account delegation',clue:true,note:'IAM Allow alone cannot add a permission the key policy does not enable.'}],questions:[Q('What explains this specific read failure?', 'The enabled key lacks an applicable key-policy access path for the app decrypt operation',['The bucket default uses SSE-KMS, so every existing object automatically moved to another key','The WAF rate rule is scoped to /login, so invoice KMS decrypt calls are counted as login traffic','The secret has a30-day rotation schedule, so KMS decrypt is automatically denied between rotations'],3,'S3 and key use are separate checks; key policy must enable a valid path. Defaults do not migrate old objects, WAF does not authorize KMS, and secret schedule does not determine key access.'),Q('Which repair is appropriate for this key-policy fixture?', 'Add a reviewed narrow decrypt principal/context path, retain administration, then test the original object',['Allow Principal:* kms:* and remove the prior key because encryption removes the need for access scope','Turn off Block Public Access because a public object no longer needs any KMS authorization path','Create a second key and only change the bucket default because the old invoice is re-encrypted on read'],0,'A narrow path plus preserved admin/recovery fits the fixture. Wildcard grants broaden access and deletion risks data loss; public access cannot bypass KMS; a default change does not re-encrypt old bytes.') ]},
      {type:'terminal',title:'🖥️ Repair protection configuration with current evidence',instructions:'ls/cat show prepared JSON. All commands are in-app fixtures; no AWS calls. Rotation and WAF checks prove stored configuration only.',goal:'<p><b>1.</b> Create customer symmetric key with key-policy.json; expected first new KeyId '+ID+'. Alias alias/shop-invoices; enable 180-day rotation. Preserve original archive key/invoices.</p><p><b>2.</b> Apply encryption.json to shop-invoices. Existing old object must remain AES256. Store TEST secret shop/db from secret.json with the new key. Configure db-secret-rotator/rotation.json with --no-rotate-immediately; then read the current secret. The fixture stores rotation configuration; AWS still tests testSecret and real runtime is unverified.</p><p><b>3.</b> Put /shop/payment-token SecureString with new key and TEST_ONLY_api_token; GetParameter with decryption. Secret/token are disposable course data.</p><p><b>4.</b> Create Regional shop-login ACL using default Allow, waf-rules.json and visibility.json. Expect first ACL Id '+ACLID+'. Associate the exact original shop-alb ARN, then GetWebACLForResource with full output. Expect reviewed rules and actual association. No HTTP traffic is run.</p><p>Keep original IDs/data/function. Missing key/policy/context, Count-only ACL, wrong target, deleted data or stale reads cannot qualify. Commands in hints are progressive; solution takes 12 actions.</p>',account:seed(),files,tasks,solution:mainSolution,hints:['Inspect the prepared policy/encryption/rotation/rules files first. Key management, secret configuration and WAF association are separate checks.',mainSolution.slice(0,4).join(' phir '),mainSolution.slice(4,9).join(' phir '),mainSolution.slice(9).join(' phir ')],success:AG.allOf(tasks),successText:'Original invoices retained. New key/defaults and retrievable TEST credentials fit reviewed state; rotation config is stored and original ALB has the reviewed current ACL association. Real rotation, WAF traffic enforcement and threat detection remain separate runtime tests.'},
      {type:'docker',title:'🐳 Lab19 — actual envelope crypto and control-plane gaps',project:'19-kms-secrets-waf',goal:'Run the owned-server lab, compare actual host crypto with metadata, and verify cleanup.',why:'Disabled-key decrypt, secret stage/default reads and unsupported finding APIs expose Moto gaps. A successful emulator response is not production protection proof.',steps:[{text:'Read README/lab.py, then run with the existing local environment.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py',expect:'14 behavior checks plus cleanup 15.7,000-byte AES-GCM roundtrip and tamper failure; KMS wrapping and S3 defaults are local Moto operations.'},{text:'Compare explicit AWSCURRENT and default secret after stage promotion; read rotation/GuardDuty gap lines.',expect:'Moto default can remain old; disabled KMS decrypt accepted; rotation period omitted; no-Lambda rotation falsely configured; GuardDuty finding endpoints404. No real DB/Lambda rotation or HTTP inspection.'},{text:'Verify owned resources cleanup and listener closure.',expect:'PASS15 owned resources removed; KMS key scheduled7days. OWNED MOTO STOPPED / LISTENER CLOSED. Own disposable server only.'}],observe:Q('Which result is actually supported by lab19?', 'Host AES-GCM authentication and local metadata/stage operations passed; runtime protection remains unverified',['Every KMS denial and WAF bot block matched AWS because a local HTTP response had success status','Lambda rotated a real PostgreSQL password because a secret reported RotationEnabled without a function','GuardDuty detected current mining traffic because creating a detector automatically generated a live incident'],1,'Actual host crypto and supported metadata operations passed; captured emulator gaps prevent broader claims. No WAF HTTP engine, DB/Lambda runtime or live GuardDuty finding ran.')},
      {type:'quiz',title:'🎓 Security decision review',questions:[
        Q('New customer objects need basic at-rest encryption, with no customer key policy requirement. Lowest operational burden?', 'SSE-S3 default encryption, with IAM/bucket access controls and the required audit scope reviewed',['Customer managed SSE-KMS for every object because SSE-S3 cannot encrypt data without manual keys','CloudHSM dedicated clusters because a basic at-rest requirement always needs single-tenant hardware','Client-side encryption for every client because server-side encryption cannot satisfy at-rest protection'],0,'SSE-S3 can satisfy this stated requirement without customer key lifecycle. KMS can add governance but is not universally mandatory; CloudHSM needs dedicated-key requirements; client-side changes plaintext exposure/operations.'),
        Q('A7,000-byte document needs authenticated client-side encryption with a KMS-managed wrapping key. Candidate?', 'Generate a data key, encrypt locally with an authenticated format, store ciphertext and wrapped key',['Send the entire document to symmetric KMS Encrypt because the ciphertext output has no size limit','Store the plaintext data key beside the encrypted document because a KMS key alias hides the bytes','Put tenant password into EncryptionContext because context is encrypted and never appears in audit logs'],1,'Direct symmetric Encrypt plaintext limit is4096bytes. Envelope encryption fits larger payload; plaintext key must be protected/discarded appropriately; context is non-secret authenticated metadata, not password storage.'),
        Q('An eligible customer symmetric AWS_KMS key needs automatic180-day material rotation. Correct expectation?', 'Enable180-day rotation; key ID and old decrypt material remain, with separate data migration if required',['Create a new key every180days and delete the old key immediately so original ciphertext stays readable','Enable automatic rotation because every customer key rotates yearly and the interval is unconfigurable','Enable rotation to rewrite all old S3 objects under a new key ID during the next successful GetObject'],2,'Eligible period90–2560days is configurable; rotation preserves identity/old material. Deleting old keys can lose data; customer rotation is opt-in; material rotation does not rewrite S3 objects or rotate DB credentials.'),
        Q('Bucket Keys are enabled and many reads reuse cached material. Which audit/cost claim is sound?', 'KMS calls can fall substantially; measure requesters/reuse and use appropriate S3 object-event auditing',['Every object GET still creates one KMS Decrypt audit event, so KMS logs contain all object accesses','All workloads save exactly99percent because requester count and access pattern cannot affect caching','Existing encrypted objects immediately gain Bucket Keys because the default configuration migrates data'],3,'Up to99% is workload-dependent. Cached Bucket Key use need not call KMS/recheck key policy per request; object audit needs selected S3 data events. Default change affects future writes, not automatic old-object migration.'),
        Q('A new AWSPENDING password exists but the DB accepts the old credential. Safe next production action?', 'Set and validate the intended backend credential, plan recovery/client refresh, then promote current',['Promote AWSCURRENT immediately because moving a secret label changes the database password implicitly','Schedule KMS material rotation because changing the wrapping key updates credentials in the database','Enable a Macie scan because identifying sensitive data makes the pending password valid for login'],0,'Stored secret and backend credential are separate. Rotation coordinates set/test then promotion/recovery; labels do not change the DB; KMS material rotation does not change a password; Macie classifies data.'),
        Q('A /login per-IP WAF rate rule blocks near100requests/60s.10,000 IPs each make few requests. What now?', 'Review distributed account/bot signals, false positives and app controls; per-IP rate alone can miss abuse',['Treat100 as an exact global account quota because WAF counts every distributed IP as one source','Change Count to Block on a different unattached ACL because association has no effect on enforcement','Disable app parameterized queries because WAF managed rules replace server-side query safety checks'],1,'Configured aggregation keys matter; distributed sources may evade per-IP thresholds. WAF estimates rather than exact quotas; the real entry resource must be associated; app query/authentication controls remain necessary.'),
        Q('A requirement asks for app customer sign-in; employees also need multiple AWS account access. Pair?', 'Cognito for app customers and IAM Identity Center for workforce AWS access, with scoped authorization',['IAM users for all customers and one shared root login for employees because both provide AWS access','Cognito identity-pool temporary credentials alone as proof that every user may read every tenant object','Secrets Manager password storage for customer sessions and CloudHSM clusters for workforce federation'],2,'Actors/trust boundaries differ. Cognito serves app identity; Identity Center serves workforce; token/credentials still require authorization. IAM/root sharing and unrelated secret/HSM tools do not solve those identity needs.'),
        Q('GuardDuty reports possible credential exfiltration on a covered workload. What does the finding establish?', 'A threat signal requiring investigation, scoped containment and recovery verification by an incident owner',['A confirmed automatic block of all stolen credentials because every GuardDuty plan prevents API calls','A guarantee every workload has runtime coverage because foundational analysis uses no optional agent','A completed incident response because Security Hub aggregation automatically rotates each affected key'],3,'A finding is a signal, not guaranteed block/remediation. Coverage/plans vary; Runtime Monitoring uses an agent; aggregation does not automatically rotate credentials. Preserve evidence and verify scoped response.')
      ]}
    ],
    interview:{title:'Interview — original ciphertext and key recovery',instructions:'Explain the boundary, then repair the original opaque TEST invoice. Commands model state/access/context; real envelope crypto is lab19.',questions:[
      Q('S3:GetObject and IAM kms:Decrypt are allowed, but no key-policy path enables decrypt. Best diagnosis?', 'The key policy must enable an applicable access path; IAM Allow alone cannot create that permission',['The S3 object must become public because public object policy overrides every key policy condition','The object should be replaced under a fresh key because a current default change preserves old ciphertext','The API should retry indefinitely because a stable missing key-policy permission is a transient network issue'],0,'Key policy controls applicable paths; default delegation/direct Allow/grants differ. Public bucket access cannot override KMS; replacement changes data; repeated deterministic AccessDenied requires configuration diagnosis.'),
      Q('An operator uses --no-rotate-immediately while changing a Lambda-based secret schedule. Expected behavior?', 'AWS still runs testSecret; stored schedule alone does not verify a successful backend password change',['AWS guarantees no Lambda invocation because the flag disables all testing and every future rotation','AWS promotes a generated current password even when the backend has no connection or rotation permissions','AWS rotates the KMS wrapping key and therefore updates every database password using that customer key'],1,'RotateImmediately=false still tests the Lambda configuration through testSecret. It is not a no-invocation promise, backend success is separate, and KMS rotation does not replace database credentials.'),
      Q('WAF update returns WAFOptimisticLockException. Which recovery preserves concurrent reviewed configuration?', 'Get the current ACL/token, review changes, then apply the intended complete config with the fresh token',['Reuse the same token repeatedly because optimistic lock errors prove no other writer changed the ACL','Delete the original ALB and recreate it because association metadata controls the web ACL lock token','Remove the rate rule and set default Allow because a simpler rule set makes stale tokens valid'],2,'Fresh read/review/update fits optimistic concurrency; blind retries reuse stale state, ALB recreation loses scope, and simplifying configuration cannot validate a stale token.'),
      Q('Capital One 2019 motivates defense review. Which statement stays within available evidence?', 'Review application/metadata and role boundaries; a documented detection capability is not prevention proof',['GuardDuty was certainly disabled, and enabling the detector would have stopped every reported data access','Encryption guarantees stolen IAM roles cannot read data even when those roles retain decrypt permission','Deploying any managed WAF rule group proves the original incident chain can never recur in another app'],3,'DOJ describes the misconfigured web application firewall and Capital One reports affected people. The lesson does not establish detector status or counterfactual prevention; authorized compromised roles and other bypasses remain possible.'),
      {terminal:{type:'terminal',title:'🖥️ Recover original key/context read',instructions:'Authorized training reviewer repairs the original key. Scope models key state, reviewed policy and crypto-use access only; it is not a full management-IAM evaluator.',goal:'<p>Original invoice-archive-key is Disabled, and reviewed decrypt access is missing. <b>1.</b> Enable the original key after dependency review. <b>2.</b> Put key-policy.json with policy-name default, preserving administration and tenant-scoped reviewer decrypt. <b>3.</b> Decrypt original fileb://invoice-cipher.bin with exact tenant shopkaro/purpose invoice context. Expect base64 Plaintext representing TEST invoice101 INR2500.</p><p>New key, changed context, broad policy, deleted invoice or old readback cannot qualify. The in-app blob is an opaque TEST handle; no real cryptography or customer data.</p>',account:seed(true),files,tasks:itasks,solution:interviewSolution,hints:['Inspect describe-key and get-key-policy; original ciphertext depends on original key plus matching context.',interviewSolution.slice(0,2).join(' phir '),interviewSolution[2]],success:AG.allOf(itasks),successText:'Original TEST ciphertext read succeeded with the original enabled key, reviewed tenant policy and exact context. No replacement/data deletion shortcut and no real HSM/cryptography claim.'}}
    ]},
    success:['Risk ko prevention/detection/response boundaries mein map kar sakta hoon','KMS key state/policy/context aur rotation limitations debug kar sakta hoon','Credential versions versus backend/runtime proof explain kar sakta hoon','WAF/GuardDuty config aur measured outcomes distinguish kar sakta hoon'],
    homework:'<p><b>Optional approved AWS sandbox only; billable.</b> Review current Region/quotas/prices and budget first. Create only owned dummy key/secret/parameters, scoped policy and test data. Verify positive/negative KMS access/context and actual encryption. Test secret rotation with an approved TEST backend/handler and client refresh; observe failures before promotion. For WAF use an owned supported entry resource, Count/canary review then appropriate enforcement; capture actual legitimate/attack request results. Configure selected GuardDuty plans/coverage and sample findings without malicious traffic. Never log real credentials or test against customer endpoints. Cleanup owned associations/ACL, parameters/secrets, data/compute/functions/roles/logs; schedule own KMS key deletion after dependency review and account for waiting-period/other ongoing charges. Follow service recovery rules; do not disable protection on shared resources.</p>',
    cards:[{front:'Encryption replaces IAM?',back:'No. At-rest encryption, plaintext access authorization and backup/recovery have different jobs.'},{front:'Direct KMS large payload?',back:'Symmetric Encrypt plaintext≤4096bytes; envelope encryption wraps a data key and encrypts/authenticates the payload locally.'},{front:'Customer key rotation?',back:'Eligible AWS_KMS symmetric automatic rotation is opt-in90–2560days; identity/old decrypt material persist. No automatic object or password rewrite.'},{front:'Bucket Keys audit trap?',back:'Up to99% savings is workload-dependent; cached reads may skip KMS calls/policy recheck. Select S3 data events for object access evidence.'},{front:'RotationEnabled means rotated?',back:'Configuration only. Backend set/test and credential/client recovery need runtime proof; no-immediate flag still tests testSecret.'},{front:'WAF rate threshold exact?',back:'No; approximate aggregation over 60/120/300/600 s, propagation and distributed/shared-IP caveats. Count observes, reviewed Block enforces.'},{front:'GuardDuty agentless?',back:'Foundational analysis differs from optional Runtime Monitoring, which uses an agent. Coverage/finding/response remain separate.'},{front:'Lab19 actual proof?',back:'Host AES-GCM roundtrip/tamper + local control-plane/stage operations. Moto disabled-key/default-secret/finding gaps; no real DB/Lambda/WAF/GuardDuty runtime.'}]
  }]);
})();
